export const DISH_MAP = new Map(DISHES.map((d) => [d.k, d]));

// Wahrscheinlichkeiten (1001 Werte, Index 0 = Hintergrund) -> die besten Gerichte
export function rankDishes(probs, n = 3) {
  const p = (c) => probs[+c + 1] || 0;
  const scored = DISHES.map((d) => [d, Object.entries(d.c).reduce((a, [c, w]) => a + p(c) * w, 0)]);
  return scored.filter(([, s]) => s > 0.004).sort((a, b) => b[1] - a[1]).slice(0, n).map(([d, s]) => ({ d, s }));
}

