const OTHER = ['a person', 'an animal', 'a room', 'a landscape', 'a screen', 'a document', 'an empty plate', 'a car'];
// Für die große KI: Kombi-Gerichte aus der Erweiterung („X mit Pommes/Reis …“) werden nicht direkt gesucht,
// weil die Erkennung Hauptgericht und Beilage jetzt einzeln findet. Sonst teilen sich fast gleiche Texte die Wahrscheinlichkeit.
const SIDE_COMBO = / mit .*(Pommes|Reis|Kartoff|püree|Püree|Nudeln|Klöß|Knödel|Spätzle|Salat|Brot|Brötchen|Cola|Bratkartoffeln|Rösti|Couscous|Bulgur)/;
const FIRST_NEW = DISHES.findIndex((d) => d.k === 'ketchup');
export const CLIP_DISHES = DISHES.filter((d, i) => i < FIRST_NEW || !SIDE_COMBO.test(d.name));
// Zwei Formulierungen je Gericht (normal und von oben fotografiert): macht die Erkennung stabiler.
const TEMPLATES = [(x) => `a photo of ${x}, a type of food.`, (x) => `a top-down photo of ${x} on a table.`];
export const CLIP_TEXTS = [...TEMPLATES.flatMap((t) => CLIP_DISHES.map((d) => t(EN[d.k]))), ...OTHER.map((o) => `a photo of ${o}.`)];
// Wahrscheinlichkeiten je CLIP_TEXTS -> die besten Gerichte. s = Anteil unter den 5 besten Vorschlägen (gut lesbar),
// raw = echte Wahrscheinlichkeit unter allen rund 1000 Gerichten. Zeigt das Foto eher kein Essen: leer.
export function rankClip(probs, n = 3) {
  const N = CLIP_DISHES.length, nT = TEMPLATES.length;
  const other = probs.slice(N * nT).reduce((a, b) => a + b, 0);
  if (other > 0.6) return [];
  const all = CLIP_DISHES.map((d, i) => { let r = 0; for (let t = 0; t < nT; t++) r += probs[t * N + i]; return { d, raw: r }; }).sort((a, b) => b.raw - a.raw);
  const top = all.slice(0, 5), sum = top.reduce((a, x) => a + x.raw, 0) || 1;
  return top.map((x) => ({ ...x, s: x.raw / sum })).filter((x) => x.raw > 0.005).slice(0, n);
}
